import React, { useState, useRef } from 'react';
import { Button } from 'primereact/button';
import { Toast } from 'primereact/toast';
import { ProgressBar } from 'primereact/progressbar';


export default function Headless() {
    const toast = useRef(null);
    const [progress, setProgress] = useState(0);
    const interval = useRef(null);

    const clear = () => {
        setProgress(0);
        toast.current.clear();
        clearInterval(interval.current);
        interval.current = undefined;
    };

    const show = () => {
        if (!interval.current) {
            toast.current.show({
                summary: 'Uploading your files.',
            });

            setProgress(0);

            if (interval.current) {
                clearInterval(interval.current);
            }

            interval.current = setInterval(() => {
                setProgress((prevProgress) => {
                    const newProgress = prevProgress + 20;

                    if (newProgress >= 100) {
                        clearInterval(interval.current);

                        return 100;
                    }

                    return newProgress;
                });
            }, 1000);
        }
    };

    return (
        <div className="">
            <Toast
            position="top-center"
            className='contrast'
                ref={toast}
                content={({ message }) => (
                    <section className="fxb fvs gp3 bg-inverted pointer-events-auto fg-white box-shadow-default fade in down rds2 pd10" >
                        <i className="pi pi-cloud-upload fg-primary font-size28"></i>
                        <div className="fxb column fvs wpr mgt2">
                            <p className=" medium-font text-base fg-white mgb5">{message.summary}</p>
                            <p className=" medium-font text-base fg-white-secondary mgb10">{message.detail}</p>
                            <div className="fxb column gp2 wpr w-100p">
                                <ProgressBar value={progress} showValue="false"></ProgressBar>
                                <label className="text-right text-xs fg-white mgb8">{progress}% uploaded...</label>
                            </div>
                            <div className="fxb gp3 mb3">
                                <Button label="Another Upload?" text className="p-0" onClick={clear}></Button>
                                <Button label="Cancel" text className="fg-white p-0" onClick={clear}></Button>
                            </div>
                        </div>
                    </section>
                )}
            ></Toast>
            <Button onClick={show} label="View" />
        </div>
    )

}